<dialog class="settings" id="settingsDialog" aria-labelledby="settingsTitle">
  <form method="dialog">
    <div class="card-head">
      <h2 id="settingsTitle">Ustawienia</h2>
      <button class="g-x" type="submit" aria-label="Zamknij ustawienia" autofocus>×</button>
    </div>
    <fieldset class="appearance-settings">
      <legend>Wygląd i język</legend>
      <label for="appTheme">Motyw aplikacji</label>
      <select id="appTheme"><option value="palarnia">Palarnia · krem i bordo</option><option value="bar">Kawiarnia · szkło i karmel</option><option value="soft">Soft · jasny relief</option><option value="line">Linia · cienka kreska</option></select>
      <label for="appMode">Tryb kolorów</label>
      <select id="appMode"><option value="system">Systemowy · jak w telefonie</option><option value="light">Dzień · jasny</option><option value="dark">Noc · ciemny</option></select>
      <label for="appDensity">Wielkość interfejsu</label>
      <select id="appDensity"><option value="standard">Standardowy</option><option value="compact">Kompaktowy</option></select>
      <label for="appLanguage">Język aplikacji</label>
      <select id="appLanguage"><option value="pl">Polski</option><option value="en">English</option></select>
    </fieldset>
    <fieldset class="alert-settings">
      <legend>Alerty parzenia</legend>
      <p class="subtle">Wybierz, jak aplikacja ma sygnalizować kolejne etapy i koniec parzenia.</p>
      <div class="alerts" role="group" aria-label="Alerty podczas parzenia">
    <button type="button" data-al="sound" aria-pressed="true"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 9h4l5-4v14l-5-4H4z"/><path d="M16 9a4 4 0 0 1 0 6M18.5 6.5a8 8 0 0 1 0 11"/></svg>Dźwięk</button>
    <button type="button" data-al="voice" aria-pressed="false"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 3a3 3 0 0 1 3 3v6a3 3 0 0 1-6 0V6a3 3 0 0 1 3-3z"/><path d="M5 11a7 7 0 0 0 14 0M12 18v3"/></svg>Głos</button>
    <button type="button" data-al="flash" aria-pressed="true"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="4" y="4" width="16" height="16" rx="3"/><path d="M4 14l5-5 4 4 3-3 4 4"/></svg>Kolor</button>
    <button type="button" class="test" id="alTest">Przetestuj alerty</button>
  </div>
    </fieldset>
    <div class="settings-links">
      <button type="button" data-jump="brewParameters">Parametry i młynki</button>
      <button type="button" data-jump="historyCard">Historia</button>
    </div>
  </form>
</dialog>
